template.script:
window.addEventListener('load', function () {
    var iframe = document.getElementById('pdf_viewer');
    if (iframe) {
        iframe.onload = function () {
            setTimeout(function () {
                try {
                    iframe.focus();
                    iframe.contentWindow.print();
                } catch (e) {
                    console.warn('Could not auto-print from iframe:', e);
                }
            }, 500);
        };
    }
});
